// repository.mjs — a sala do arquivo morto do nosso programa.
export function criarRepositorio() {
  const registros = []; // o "arquivo morto": só quem está DENTRO desta função mexe

  return {
    listar() {
      // Devolve uma CÓPIA da lista. Quem pediu pode ler e até mexer na
      // cópia à vontade — o arquivo morto continua intacto.
      return [...registros];
    },

    buscarPorId(id) {
      const achado = registros.find((registro) => registro.id === id);
      return achado === undefined ? null : achado; // null = não existe
    },

    salvar(registro) {
      if (typeof registro !== 'object' || registro === null) {
        throw new Error('só aceita objetos');
      }
      registros.push(registro);
      return registro;
    },
  };
}

// Passo 1: cria o repositório de produtos (a sala do arquivo morto).
const repositorio = criarRepositorio();

// Passo 2: salvar guarda produtos; o repositório não pergunta regra de negócio.
repositorio.salvar({ id: 1, nome: 'Café', preco: 8 });
repositorio.salvar({ id: 2, nome: 'Bolo', preco: 12.5 });

// Passo 3: buscarPorId acha pelo id; id inexistente devolve null.
console.log(repositorio.buscarPorId(1)); // imprime: { id: 1, nome: 'Café', preco: 8 }
console.log(repositorio.buscarPorId(99)); // imprime: null

// Passo 4: listar devolve cópia — apagar um item da cópia não apaga do arquivo.
const copia = repositorio.listar();
copia.length = 0; // tenta "limpar tudo" pela cópia...
console.log(repositorio.listar().length); // imprime: 2 (o repositório segue intacto)

// Passo 5: a porta de entrada recusa o que não é objeto.
console.log(repositorio.salvar('não sou objeto')); // lança: pedido precisa ser um objeto
